const targetTypeGuid = '277768b5-9220-4312-bf0d-ab82d9fb6a73';
const browser = await chromium.launch({ headless: true, args:['--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
const page = await browser.newPage();
page.on('console', (msg) => console.log('[browser]', msg.type(), msg.text()));
page.on('pageerror', (err) => console.log('[pageerror]', err.message));
const zipBytes = await readFile(path.resolve('../assets/compose/metabolism.zip'));
const { kit } = await importKitArchive(zipBytes);
await page.goto('http://127.0.0.1:4183/', { waitUntil: 'commit' });
await page.waitForTimeout(2000);
await page.evaluate(async ({ kitPayload, typeGuid }) => {
  const store = (window as any).__COMPOSE_STORE__;
  await store.execute('compose.sketchpad.createKit', 'compose.sketchpad.probe', kitPayload, false, false);
  (window as any).__COMPOSE_NAVIGATE__(`/kits/${kitPayload.guid}/types/${typeGuid}`);
}, { kitPayload: kit, typeGuid: targetTypeGuid });
await page.waitForURL(/\/types\//, { timeout: 30000 });
await page.waitForTimeout(10000);
console.log('url', page.url());
console.log('canvasCount', await page.locator('canvas').count());
console.log('bodyPreview', (await page.locator('body').textContent())?.slice(0, 500));
console.log('cameraState', await page.evaluate(() => {
  const actor = (window as any).__COMPOSE_ACTOR__;
  const snapshot = actor?.getSnapshot?.();
  const url = window.location.pathname;
  const m = url.match(/\/kits\/([^/]+)\/types\/([^/]+)/);
  const key = m ? `${m[1]}:${m[2]}` : null;
  return key ? snapshot?.context?.typeApps?.[key]?.camera ?? null : null;
}));
const canvas = page.locator('canvas').first();
const visible = await canvas.isVisible().catch(() => false);
console.log('canvasVisible', visible);
if (visible) {
  const box = await canvas.boundingBox();
  console.log('box', box);
  const centerX = box!.x + box!.width / 2;
  const centerY = box!.y + box!.height / 2;
  await page.mouse.move(centerX, centerY);
  await page.mouse.down();
  const start = Date.now();
  await page.mouse.move(centerX + 150, centerY + 100);
  await page.mouse.up();
  console.log('panDuration', Date.now() - start);
}
await browser.close();
EOF

